import{_ as a,a0 as r,w as u,s as p,ao as l,I as i,x as n,a1 as s,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"[小白技巧]如何在Linux中知道你的系統是否有USB 3.0 端口 | LCTT x X-CMD","titleTemplate":false,"description":"[小白技巧]如何在Linux中知道你的系統是否有USB 3.0 端口 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"[小白技巧]如何在Linux中知道你的系統是否有USB 3.0 端口 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"[小白技巧]如何在Linux中知道你的系統是否有USB 3.0 端口 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140609 How To Know If Your System Has USB 3.0 Port In Linux [Quick Tip]","title":"[小白技巧]如何在Linux中知道你的系統是否有USB 3.0 端口","tag":"201406","desc":""},"relativePath":"201406/20140609 How To Know If Your System Has USB 3.0 Port In Linux [Quick Tip].md","filePath":"[post].md"}'),d={name:"201406/20140609 How To Know If Your System Has USB 3.0 Port In Linux [Quick Tip].md"};function S(x,t,f,m,B,U){const o=r("Link");return u(),p("div",null,[t[11]||(t[11]=l(`<h1 id="小白技巧-如何在linux中知道你的系統是否有usb-3-0-端口" tabindex="-1">[小白技巧]如何在Linux中知道你的系統是否有USB 3.0 端口 <a class="header-anchor" href="#小白技巧-如何在linux中知道你的系統是否有usb-3-0-端口" aria-label="Permalink to “[小白技巧]如何在Linux中知道你的系統是否有USB 3.0 端口”">​</a></h1><p>近來的大多數的新計算機都有了USB 3.0接口了。但是<strong>你怎麼知道你的計算機有沒有USB 3.0接口</strong>？這篇短文中，我們會告訴如何在Linux下知道你的系統上有USB 3還是USB3接口。</p><h3 id="在linux終端中檢測是否有usb-3-0-端口" tabindex="-1">在Linux終端中檢測是否有USB 3.0 端口 <a class="header-anchor" href="#在linux終端中檢測是否有usb-3-0-端口" aria-label="Permalink to “在Linux終端中檢測是否有USB 3.0 端口”">​</a></h3><p>打開一個終端,並使用下面的命令:</p><pre><code>lsusb
</code></pre><p>這個命令會顯示你係統下USB的總線信息。檢查一下結果，如果你看到像“3.0 root hub”字樣，這意味着你係統有USB 3.0。比如，在我的電腦上，它這樣顯示：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/06/Know_Usb3_Ubuntu_Linux.jpeg" alt="How to find if system has USB 3.0 in Linux"></p><p>這個技巧在所有的Linux系統上，像Ubuntu，Linux Mint，Fedora等等都有效。現在當你知道你有USB 3.0 端口之後，**如何辨別哪個口是USB 3.0,哪個是USB 2.0。</p><h3 id="辨別哪個口是usb-3-0" tabindex="-1">辨別哪個口是USB 3.0 <a class="header-anchor" href="#辨別哪個口是usb-3-0" aria-label="Permalink to “辨別哪個口是USB 3.0”">​</a></h3><p>通常USB 3.0 口被標記為SS（“Super Speed”的縮寫）。如果你的系統製造商沒有標記SS或者USB 3,那麼你可以檢查端口的內部通常是藍色的。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2014/06/usb3.0port.jpg" alt="find usb 3.0 port"></p><p>我希望這個快捷提示能夠幫助你知道你係統是否有USB 3.0 並可以分辨出USB 3.0 口</p><hr>`,13)),i("p",null,[t[1]||(t[1]=n("via: ",-1)),s(o,{href:"http://itsfoss.com/find-usb-3-port-linux/"},{default:e(()=>[...t[0]||(t[0]=[n("http://itsfoss.com/find-usb-3-port-linux/",-1)])]),_:1})]),i("p",null,[t[4]||(t[4]=n("譯者：",-1)),s(o,{href:"https://github.com/geekpi"},{default:e(()=>[...t[2]||(t[2]=[n("geekpi",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=n("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),s(o,{href:"http://linux.cn/"},{default:e(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const b=a(d,[["render",S]]);export{_ as __pageData,b as default};
